import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Stock } from '../src/stock.mjs';
import { ReservationBook } from '../src/reservations.mjs';
import { handleReserve } from '../src/api.mjs';

const setup = () => {
  const stock = new Stock([{ warehouse: 'w1', sku: 'cap', onHand: 2, priority: 1 }]);
  return new ReservationBook(stock, () => 0);
};

test('handleReserve returns 201 with the reservation on success', () => {
  const book = setup();
  const result = handleReserve(book, { orderId: 'o1', sku: 'cap', quantity: 2 });
  assert.equal(result.status, 201);
  assert.equal(result.body.status, 'held');
});

test('handleReserve maps insufficient_stock to 409', () => {
  const book = setup();
  const result = handleReserve(book, { orderId: 'o1', sku: 'cap', quantity: 3 });
  assert.deepEqual(result, { status: 409, body: { error: 'insufficient_stock' } });
});

test('handleReserve maps invalid_request and invalid_quantity to 400', () => {
  const book = setup();
  assert.equal(handleReserve(book, { orderId: '', sku: 'cap', quantity: 1 }).status, 400);
  assert.equal(handleReserve(book, { orderId: 'o1', sku: 'cap', quantity: -1 }).status, 400);
});

test('handleReserve maps unexpected errors to 500', () => {
  const book = { reserve: () => { throw new Error('boom'); } };
  const result = handleReserve(book, {});
  assert.deepEqual(result, { status: 500, body: { error: 'internal' } });
});

import { roundHalfEven } from './money.mjs';

export function priceOrder({ lines, coupons = [] }) {
  if (!Array.isArray(lines) || lines.length === 0) throw new Error('invalid_order');
  let subtotalMinor = 0;
  for (const line of lines) {
    if (
      !Number.isSafeInteger(line.unitMinor) ||
      line.unitMinor < 0 ||
      !Number.isSafeInteger(line.quantity) ||
      line.quantity <= 0
    )
      throw new Error('invalid_order');
    subtotalMinor += line.unitMinor * line.quantity;
  }

  for (const coupon of coupons) {
    if (coupon && coupon.type === 'percent') {
      if (!Number.isInteger(coupon.value) || coupon.value < 1 || coupon.value > 100)
        throw new Error('invalid_coupon');
    } else if (coupon && coupon.type === 'fixed') {
      if (!Number.isSafeInteger(coupon.value) || coupon.value <= 0) throw new Error('invalid_coupon');
    } else {
      throw new Error('invalid_coupon');
    }
  }

  let totalMinor = subtotalMinor;
  for (const coupon of coupons) {
    if (coupon.type === 'percent') totalMinor -= roundHalfEven(totalMinor * coupon.value, 100);
  }
  for (const coupon of coupons) {
    if (coupon.type === 'fixed') totalMinor -= coupon.value;
  }
  totalMinor = Math.max(0, totalMinor);

  return { subtotalMinor, discountMinor: subtotalMinor - totalMinor, totalMinor };
}

